import{_ as n,C as r,c as l,o as f,ag as o,j as e,G as s,a as t}from"./chunks/framework.Bw-5EFTY.js";const P=JSON.parse('{"title":"Paid Memberships Pro Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/paid-memberships-pro-integration-with-fluentaffiliate.md","filePath":"guide/integrations/paid-memberships-pro-integration-with-fluentaffiliate.md","lastUpdated":1755603747000}'),p={name:"guide/integrations/paid-memberships-pro-integration-with-fluentaffiliate.md"};function m(h,i,u,d,g,c){const a=r("ZoomableImage");return f(),l("div",null,[i[0]||(i[0]=o('<h1 id="paid-memberships-pro-integration-with-fluentaffiliate" tabindex="-1">Paid Memberships Pro Integration with FluentAffiliate <a class="header-anchor" href="#paid-memberships-pro-integration-with-fluentaffiliate" aria-label="Permalink to &quot;Paid Memberships Pro Integration with FluentAffiliate&quot;">​</a></h1><p>Paid Memberships Pro is a powerful membership plugin for WordPress, designed to help you create and manage your membership site with ease. By integrating it with FluentAffiliate, you can seamlessly manage affiliate commissions for your membership sales, track referrals, and grow your affiliate program.</p><p>In this guide, we&#39;ll walk you through how to connect Paid Memberships Pro with FluentAffiliate step by step.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Paid Membership Pro is a pro feature of FluentAffiliate. To use it, you need FluentAffiliate Pro.</p><p>To get started, you first need to install and activate both the Paid Memberships Pro and FluentAffiliate plugins on your WordPress website.</p></div><h2 id="enable-paid-memberships-pro-in-fluentaffiliate" tabindex="-1">Enable Paid Memberships Pro in FluentAffiliate <a class="header-anchor" href="#enable-paid-memberships-pro-in-fluentaffiliate" aria-label="Permalink to &quot;Enable Paid Memberships Pro in FluentAffiliate&quot;">​</a></h2><p>Once both plugins are active, you need to enable the integration from the FluentAffiliate dashboard.</p><ol><li>Go to the <strong>FluentAffiliate Dashboard</strong>.</li><li>From there, click on the <strong>Settings</strong> tab in the top menu.</li><li>On the left sidebar, you&#39;ll find an option called <strong>Integration Settings</strong>. Simply click on that.</li><li>Inside Integration Settings, you&#39;ll see a list of different integration options. Find <strong>Paid Memberships Pro</strong> in this list.</li><li>Now, simply click on the <strong>toggle</strong> button to enable the Paid Memberships Pro integration with FluentAffiliate.</li></ol><p>Your Paid Memberships Pro integration is now active, allowing affiliates to earn referral commissions on membership sales.</p><p>In the <strong>Manage</strong> section, you&#39;ll find additional settings to customize how affiliate commissions work.</p>',9)),e("p",null,[s(a,{src:"/guide/public/images/integrations/paid-memberships-pro/integration-setup-options.webp",alt:"Integration Settings"})]),i[1]||(i[1]=e("h2",{id:"configure-paid-memberships-pro-settings",tabindex:"-1"},[t("Configure Paid Memberships Pro Settings "),e("a",{class:"header-anchor",href:"#configure-paid-memberships-pro-settings","aria-label":'Permalink to "Configure Paid Memberships Pro Settings"'},"​")],-1)),i[2]||(i[2]=e("p",null,[t("After clicking the "),e("strong",null,"Manage"),t(" button, a pop-up will appear where you'll find important settings to manage how affiliate commissions are handled. You can enable or disable these options based on your preferences.")],-1)),i[3]||(i[3]=e("ul",null,[e("li",null,[e("strong",null,"Enable Affiliate Integration for Paid Memberships Pro:"),t(" If this option is enabled (checked), affiliates will be able to earn commissions on sales from your Paid Memberships Pro levels.")]),e("li",null,[e("strong",null,"Enable custom rate for specific membership or categories:"),t(" Use this setting to override the default affiliate commission rate. Checking this box allows you to configure specific, custom rates for your affiliates based on different membership levels.")])],-1)),e("p",null,[s(a,{src:"/guide/public/images/integrations/paid-memberships-pro/paid-memberships-pro-settings-configuration.webp",alt:"Paid Memberships Pro Settings"})]),i[4]||(i[4]=o('<h3 id="custom-affiliate-rate-configuration" tabindex="-1">Custom Affiliate Rate Configuration <a class="header-anchor" href="#custom-affiliate-rate-configuration" aria-label="Permalink to &quot;Custom Affiliate Rate Configuration&quot;">​</a></h3><p>Once <strong>Custom Affiliate Rate</strong> is enabled, you can define specific commission structures for different membership levels.</p><ol><li>Click on the <strong>+Add New Group</strong> button to create your first custom rate. <ul><li><strong>Selected Products:</strong> This option allows you to apply the custom rate to specific membership levels. Enter a keyword in the text field to search for and select the membership(s) to which this custom rate will apply.</li><li><strong>Select Rate:</strong> Set the commission rate for the selected membership levels.</li><li><strong>Rate Type Selector:</strong> Click the dropdown menu to choose the type of commission: <ul><li><strong>Percentage:</strong> The affiliate will receive a percentage of the sale price as commission.</li><li><strong>Fixed:</strong> The affiliate will receive a fixed amount as commission, regardless of the sale price.</li></ul></li></ul></li><li><strong>Add More Rates:</strong> After configuring the rate, you can click the <strong>+Add New Group</strong> button again to add more custom rates for other membership levels. You can also delete a rate by clicking the delete icon on the right side.</li><li>Once all your custom rates are added, click the <strong>Save Settings</strong> button to apply them.</li></ol><h2 id="generate-an-affiliate-link" tabindex="-1">Generate an Affiliate Link <a class="header-anchor" href="#generate-an-affiliate-link" aria-label="Permalink to &quot;Generate an Affiliate Link&quot;">​</a></h2><p>After you&#39;ve completed configuring the Paid Memberships Pro affiliate settings, the next step is for your affiliates to log in to their <strong>Affiliate Area</strong> provided by FluentAffiliate. To learn more about <a href="/guide/affiliate-portal/generating-affiliate-links">affiliate link</a>, read this article.</p><p>If someone purchases a membership using the affiliate link, the affiliate will earn a commission based on the settings you&#39;ve configured.</p>',6))])}const w=n(p,[["render",m]]);export{P as __pageData,w as default};
